import { Kysely, sql } from 'kysely';
import { APP_ROLE, SYSTEM_ROLE } from '../roles';
import { tenantRls } from './helpers';

/**
 * Background exports (AUD-02 audit log exports, and later other reports) and delivery signatures.
 *
 * An export is requested through the API, generated by the worker, stored in file storage and
 * downloaded through a short-lived signed link. The file expires; the record of who exported
 * what stays forever.
 */
export async function up(db: Kysely<unknown>): Promise<void> {
  await sql
    .raw(
      `
    CREATE TABLE exports (
      id              uuid PRIMARY KEY,
      organization_id uuid NOT NULL REFERENCES organizations(id),
      kind            text NOT NULL CHECK (kind IN ('audit_log')),
      format          text NOT NULL CHECK (format IN ('csv','pdf')),
      filters         jsonb NOT NULL DEFAULT '{}'::jsonb,
      status          text NOT NULL DEFAULT 'queued' CHECK (status IN ('queued','running','done','failed','expired')),
      row_count       integer,
      file_key        text,
      file_size       bigint,
      error           text,
      attempts        integer NOT NULL DEFAULT 0,
      requested_by    uuid NOT NULL,
      created_at      timestamptz NOT NULL DEFAULT now(),
      started_at      timestamptz,
      finished_at     timestamptz,
      expires_at      timestamptz,
      UNIQUE (organization_id, id),
      FOREIGN KEY (organization_id, requested_by) REFERENCES users (organization_id, id),
      CHECK (status <> 'done' OR (file_key IS NOT NULL AND row_count IS NOT NULL AND expires_at IS NOT NULL))
    );
    CREATE INDEX exports_queue_idx ON exports (created_at) WHERE status IN ('queued','running');
    CREATE INDEX exports_org_idx   ON exports (organization_id, created_at DESC);
    REVOKE DELETE ON exports FROM ${APP_ROLE}, ${SYSTEM_ROLE};

    -- DEL-03: optional signature captured at the door, stored in file storage.
    ALTER TABLE deliveries ADD COLUMN signature_key text;

    -- Filtering the audit log by who did it.
    CREATE INDEX IF NOT EXISTS audit_log_org_actor_idx ON audit_log (organization_id, actor_id, occurred_at DESC);
    CREATE INDEX IF NOT EXISTS audit_log_org_action_idx ON audit_log (organization_id, action_type, occurred_at DESC);

    ${tenantRls('exports')}
  `,
    )
    .execute(db);
}

export async function down(db: Kysely<unknown>): Promise<void> {
  await sql
    .raw(
      `
    DROP INDEX IF EXISTS audit_log_org_action_idx;
    DROP INDEX IF EXISTS audit_log_org_actor_idx;
    ALTER TABLE deliveries DROP COLUMN IF EXISTS signature_key;
    DROP TABLE IF EXISTS exports;
  `,
    )
    .execute(db);
}
